parameters.jsCode:
const jsonWorkflow = $input.first().json;

// Propiedades aceptadas para la api de creación de flujos, garantizando que solo estas se envíen dentro del bloque settings para evitar errores en la creación por enviar propiedades deprecadas 
const allowedSettings = [
  'saveExecutionProgress',
  'saveManualExecutions',
  'saveDataErrorExecution',
  'saveDataSuccessExecution',
  'executionTimeout',
  'errorWorkflow',
  'timezone',
  'executionOrder',
  'callerPolicy',
  'callerIds',
  'timeSavedPerExecution',
  'availableInMCP',
  'redactionPolicy',
  'customTelemetryTags'
];

const cleanSettings = {};
for (const key of allowedSettings) {
  if (jsonWorkflow.settings?.[key] !== undefined) {
    cleanSettings[key] = jsonWorkflow.settings[key];
  }
}

return [
  {
    content: {
      ...jsonWorkflow,
      settings: cleanSettings,
    },
    id: jsonWorkflow.id,
    name: jsonWorkflow.name
  }
]

function getGithubFileID(filename) {
  const separator = $('config').first().json.separator_character;
  const clean = filename.replace(/\.json$/, '');
  const parts = clean.split(separator);
  return {
    id: parts[0]
  };
}

/**
 * Determinar cuales workflows no han sido restaurados aun según los registros en la tabla de control
 */
const workflows = $('get_restored_workflows').all();
let pending = [];
for (const item of $('get_only_workflows').all()) {
  const { id } = getGithubFileID(item.json.name);
  const restored = workflows.some(item => item.json.workflow_id === id);
  if (!restored){
    pending.push(item.json)
  }
}

return pending;

